<?php
require_once __DIR__.'/../includes/functions.php';require_role(['admin']);$where='1=1';$params=[];$status=$_GET['status']??'';$from=$_GET['from']??'';$to=$_GET['to']??'';if(in_array($status,['Pending','Accepted','Rejected','Collected'],true)){$where.=' AND r.status=?';$params[]=$status;}if($from&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where.=' AND DATE(r.requested_at)>=?';$params[]=$from;}if($to&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where.=' AND DATE(r.requested_at)<=?';$params[]=$to;}$stmt=$pdo->prepare("SELECT r.*,d.food_name,du.name donor_name,ru.name recipient_name FROM collection_requests r JOIN food_donations d ON d.id=r.donation_id JOIN users du ON du.id=d.donor_id JOIN users ru ON ru.id=r.recipient_id WHERE $where ORDER BY r.requested_at DESC");$stmt->execute($params);$requests=$stmt->fetchAll();$page_title='Collection requests | SharePlate';require __DIR__.'/../includes/header.php';?>
<section class="page-hero compact"><div class="container"><p class="eyebrow">Administration</p><h1>Collection requests</h1><div class="admin-nav"><a href="dashboard.php">Overview</a><a href="users.php">Users</a><a href="donations.php">Donations & reports</a><a href="requests.php">Requests</a></div></div></section><section class="container section"><form class="filter-bar" method="get"><input type="date" name="from" aria-label="From date" value="<?=e($from)?>"><input type="date" name="to" aria-label="To date" value="<?=e($to)?>"><select name="status"><option value="">All statuses</option><?php foreach(['Pending','Accepted','Rejected','Collected'] as $s):?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="button">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Food</th><th>Donor</th><th>Recipient</th><th>Quantity</th><th>Status</th><th>Requested</th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><?=e($r['food_name'])?></td><td><?=e($r['donor_name'])?></td><td><?=e($r['recipient_name'])?></td><td><?=e($r['requested_quantity'])?></td><td><?=e($r['status'])?></td><td><?=e(format_datetime($r['requested_at']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>